    return(outVec.rgb);
}

RayHit sphereHit( vec3 sphOri, float radius, vec3 camDir, vec3 camOri ) {

    //check if ray intersects sphere
    float camDiff = dot(camOri - sphOri, camDir);
    float descrim = pow(camDiff, 2.) - pow(length(camOri - sphOri), 2.) + pow(radius, 2.);

    if(descrim < 0. || camDiff > 0. ) {
        return( RayHit(false, vec3(0.), 10000000., vec3(0.), vec4(0.), blank) );
    }

    //find distance to intersection
    vec3 pos = camOri + camDir*(-camDiff-sqrt(descrim));
    vec3 nor = normalize(pos - sphOri);

    return( RayHit(true, pos, -camDiff-sqrt(descrim), nor, vec4(1.), blank) );

}

RayHit planeHit( vec3 point, vec3 normal, vec3 camDir, vec3 camOri ) {

    //check if ray is parallel to plane
    normal = normalize(normal);
    float descrim = dot(normal, camDir);

    if( descrim == 0. ) { 
        return( RayHit(false, vec3(0.), 10000000., vec3(0.), vec4(0.), blank) ); 
    }

    //find distance between ray and plane, discard negative distances
    float plDist = -dot(camOri-point, normal) / descrim;

    if( plDist < 0. ) {
        return( RayHit(false, vec3(0.), 10000000., vec3(0.), vec4(0.), blank) );
    }
    return( RayHit(true, camOri + camDir * plDist, plDist, normal, vec4(.5, 1., .5, 1.), blank) );

}

RayHit triangleHit( vec3 point1, vec3 point2, vec3 point3, vec3 camDir, vec3 camOri ) {

    //intersect with a plane
    vec3 normal = normalize( cross(point2-point1, point3-point1) );
    float descrim = dot(normal, camDir);

    if( descrim == 0.) {
        return( RayHit(false, vec3(0.), 10000000., vec3(0.), vec4(0.), blank) ); 
    }

    float triDist = -dot(camOri-point1, normal) / descrim;
    vec3 rayPoint = camOri + camDir * triDist;

    //normalized vectors of the triangle sides within the plane
    vec3 ab = normalize(point2 - point1);
    vec3 bc = normalize(point3 - point2);
    vec3 ca = normalize(point1 - point3);

    //angle between two adjacent sides
    float triMin1 = dot(ab, -ca);
    float triMin2 = dot(bc, -ab);
    float triMin3 = dot(ca, -bc);

    //angle between point and one side
    float triAng1 = dot(ab, normalize(rayPoint - point1));
    float triAng2 = dot(bc, normalize(rayPoint - point2));
    float triAng3 = dot(ca, normalize(rayPoint - point3));

    //check to see if the point lies inside the range of all 3 angles
    if( triAng1 < triMin1 || triAng2 < triMin2 || triAng3 < triMin3 || triDist < 0.) {
        return( RayHit(false, vec3(0.), 10000000., vec3(0.), vec4(0.), blank) );      
    }
    return( RayHit(true, rayPoint, triDist, normal, vec4(.8, .5, .8, 1.), blank) );

}

RayHit raycast( Object obj, vec3 camDir, vec3 camOri ) {
    RayHit ray;

    if( obj.type == 0 ) {
        ray = sphereHit( obj.ori, obj.rad, camDir, camOri );
    }
    if( obj.type == 1 ) {
        ray = planeHit( obj.ori, obj.norm, camDir, camOri );
    }
    if( obj.type == 2 ) {
        ray = triangleHit( obj.ori, obj.point1, obj.point2, camDir, camOri );
    }
    ray.obj = obj;

    return( ray );
}

RayHit raycastScene( Object[objNum] objs, vec3 camDir, vec3 camOri, int objId ) {
    bool hit = false;
    RayHit ray;
    RayHit tempRay;

    for( int i = 0; i < objs.length(); i++) {

        tempRay = raycast( objs[i], camDir, camOri ) ;

        if( tempRay.hit == true && (tempRay.dist <= ray.dist || hit == false) && tempRay.obj.id != objId ) {
            hit = true;
            ray = tempRay;
            ray.obj = objs[i];
        }

    }
    return( ray );
}

vec3 calcLight( vec3 norm, vec3 lightDir, vec3 camDir, float dist, Material mat, vec3 ambCol, vec3 lightCol ) {
    float diffFac = mat.diff * max(0., dot(norm, lightDir));
    float specFac = mat.spec * pow(max(0., dot(reflect(lightDir, norm), camDir)), mat.smot);
    float scatFac = exp(-.05*dist);

    vec3 col = ( .5*mat.refl*lightCol + diffFac*lightCol + lightCol*specFac) * mat.dCol.xyz;

    return( max(1.-mat.emit, 0.)*mix(ambCol, col, scatFac) + 1.5*mat.emit*mix(ambCol, mat.eCol, 0.*scatFac+1.) );
}

