void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord/iResolution.y)*2. - vec2(iResolution.x/iResolution.y, 1.);

    vec3 col = vec3(uv, 0.0);

    //initialize camera
    vec3 camOri = vec3(0.);
    vec3 camDir = normalize(vec3(uv, 1.5));

    vec3 rayPos = camOri;
    float rayDist = 0.;
    bool hit = false;

    float theta = 6.28*(iMouse.x/iResolution.x - 1.);
    float phi = 3.14*(iMouse.y/iResolution.y - .5);
    phi = 0.;
    mat3 yRot = mat3(vec3(cos(theta), 0., -sin(theta)), vec3(0., 1., 0.), vec3(sin(theta), 0., cos(theta)));
    mat3 xRot = mat3(vec3(1., 0., 0.), vec3(0., cos(phi), sin(phi)), vec3(0., -sin(phi), cos(phi)))*yRot;

    camDir *= xRot * yRot;
    vec3 forwardVec = vec3(0., 0., 1.) * xRot * yRot;
    vec3 upVec = vec3(0., 1., 0.) * xRot * yRot;
    vec3 rightVec = cross(forwardVec, upVec);


    objects[7].ori = camOri - forwardVec*0.1 + upVec*.5;
    objects[7].point2 = camOri - forwardVec*0.1 - upVec*.5 + .5*rightVec;
    objects[7].point1 = camOri - forwardVec*0.1 - upVec*.5 - .5*rightVec;

    vec3 baseCamDir = camDir;
    float retinaSize = mix(.5, 0., pow(texture(iChannel0, fragCoord/iResolution.xy).w, .1));
    float focalLength = 5.*iMouse.y/iResolution.y;
    vec3 randomVec = retinaSize*(2.*randVec3( iFrame, vec3(0.)) - vec3(1.));
    vec3 offSet = camOri + randomVec.x*upVec + randomVec.y*rightVec;
    camDir = normalize((camOri + focalLength*camDir) - offSet);
    camOri = offSet;

    vec2 mousePos = (iMouse.xy/iResolution.y)*2. - vec2(iResolution.x/iResolution.y, 1.);

    //initialize sun and ambient lighting
    vec3 sunPos = normalize(vec3(.1, .7, -.6));
    vec3 sunCol = vec3(1., 1., .7);    
    //vec3 ambCol = vec3(.8, .95, .95);
    vec3 ambCol = vec3(.95, 1., .98);
    //ambCol = vec3(0.);
    objects[0].ori = sunPos * 250.;

    //raytrace meshes
    RayHit ray = raycastScene( objects, camDir, camOri, 0 );

        //col = vec3(ray.dist * 0.05);

    Object obj = ray.obj;
    Material oMat = obj.mat;
    if( ray.hit == false ) {
        col = mix(ambCol, texture(iChannel2, baseCamDir).rgb, min(1.5*camDir.y, 1.));
    } else {
        col = vec3(0.);
        vec3 refCol = vec3(0.);
        vec3 refDir = reflect( camDir, ray.norm );

        //this integer controls the number of rays sent out for indirect lighting and reflections;
        int reflNum = 1;

        for( int j = 0; j < reflNum; j++) {
            vec3 tempDir = normalize( refDir + oMat.refl*normalize( 2.*randVec3( j + 1 + iFrame, pow(ray.posn+camDir, vec3(1.)) ) - vec3(1.) ) );
            RayHit tempRay = raycastScene( objects, tempDir, ray.posn, obj.id );
            Object refObj = tempRay.obj;

            if( tempRay.hit == false) {
                refCol = 1.5*mix(ambCol, texture(iChannel2, tempDir).rgb, min(1.5*tempDir.y, 1.));
            } else {
                //refObj.mat.refl = .9;

                refCol = calcLight( tempRay.norm, sunPos, tempDir, tempRay.dist, refObj.mat, ambCol, sunCol );
            }



            col += calcLight( ray.norm, tempDir, camDir, ray.dist, oMat, ambCol, refCol );
        }

        col *= 1./ float(reflNum);


        //col = calcLight( ray.norm, sunPos, camDir, ray.dist, oMat, ambCol, refCol );
        //col = vec3(-ray.dist);
    }
    // add to buffer, reset buffer when camera moves
    fragColor = (texture(iChannel0, fragCoord/iResolution.xy) + vec4(col,0.));
    fragColor.w *= 1.0/(1.0+fragColor.w);
    if(iMouse.z > 0. || iFrame == 0) {
        fragColor = vec4(col,1.0);
    }

}
